 p.chmod(0o600);s=p.stat();assert s.st_nlink==1 and s.st_size==row['bytes']and stat.S_IMODE(s.st_mode)==row['mode']and hashlib.sha256(p.read_bytes()).hexdigest()==row['sha256']
